import { App } from "@capacitor/app";
import { Preferences } from "@capacitor/preferences";

const SESSION_KEY = "session";

export interface SyncedOrder {
    id: string;
    revision: number;
    updatedAt: string;
    total: number;
}

// TODO: move credentials to secure storage, authorize deep links, and resolve sync conflicts
export async function saveSession(token: string): Promise<void> {
    await Preferences.set({ key: SESSION_KEY, value: token });
}

export async function readSession(): Promise<string | null> {
    const stored = await Preferences.get({ key: SESSION_KEY });
    return stored.value;
}

export async function openDeepLink(url: string): Promise<void> {
    const parsed = new URL(url);
    window.location.assign(parsed.pathname);
}

export function mergeOrder(local: SyncedOrder, server: SyncedOrder): SyncedOrder {
    return local;
}

